(function(E){ const x = E["hr-m7"] = E["hr-m7"] || {units:{}}; x.units["hr-cp-7"] = {"writing":{"id":"c-hr-cp-7-w","course":"hr","unit":"hr-cp-7","title":{"en":"Rania's probation review letter","tr":"Rania’nın deneme süresi değerlendirme mektubu","fa":"نامه‌ی ارزیابی دوره‌ی آزمایشی رانیا"},"type":"writing","difficulty":"hard","portfolio":null,"prompt":{"en":"Write Rania's probation review letter (80-110 words): the review meeting, the result (probation passed), two strengths with facts, one area to develop, and what happens next.","tr":"Rania’nın deneme süresi değerlendirme mektubunu yaz (80-110 kelime): değerlendirme görüşmesi, sonuç (deneme süresini geçti), olgularla iki güçlü yan, gelişecek bir alan ve sonraki adım.","fa":"نامه‌ی ارزیابی دوره‌ی آزمایشی رانیا را بنویس (۸۰ تا ۱۱۰ کلمه): جلسه‌ی ارزیابی، نتیجه (دوره‌ی آزمایشی را گذرانده)، دو نقطه‌ی قوت با واقعیت‌ها، یک زمینه برای رشد و قدم بعدی."},"model":"Dear Rania, following your probation review on 2 March, I am pleased to confirm that you have passed your probation period. Since you joined, you have cut picking errors from 4% to 1.5%, and the new loading plan has saved two hours a day. One area to develop is delegation: at the moment you check every route yourself. As a result, we would like you to attend the team leader course in April. Your contract continues on the same terms. Please contact me if you have any questions. Yours sincerely, Leyla Karimi","frame":"Dear ___, following your probation review on ___, I am pleased to confirm that ___. Since you joined, you have ___, and ___. One area to develop is ___. As a result, ___. Your contract ___. Yours sincerely, ___","words":[{"word":"following"},{"word":"since you joined"},{"word":"as a result"}],"minWords":80,"minSentences":6,"rubric":["Task done: meeting, result, two strengths, one area, next step","Organised: result first, then facts, then development and next step","Language: formal linking and the present perfect for results","Tone: warm, formal and specific"],"rubricI18n":{"tr":["Görev: görüşme, sonuç, iki güçlü yan, bir alan, sonraki adım","Düzen: önce sonuç, sonra olgular, sonra gelişim ve sonraki adım","Dil: resmî bağlaçlar ve sonuçlar için present perfect","Üslup: sıcak, resmî ve net"],"fa":["کامل بودن کار: جلسه، نتیجه، دو نقطه‌ی قوت، یک زمینه، قدم بعدی","نظم: اول نتیجه، بعد واقعیت‌ها، بعد رشد و قدم بعدی","زبان: ربط‌دهنده‌های رسمی و حال کامل برای نتیجه‌ها","لحن: گرم، رسمی و دقیق"]},"parts":[{"t":{"en":"The review meeting","tr":"Değerlendirme görüşmesi","fa":"جلسه‌ی ارزیابی"},"find":["following your probation review","following"],"sample":"the review on 2 March"},{"t":{"en":"The result","tr":"Sonuç","fa":"نتیجه"},"find":["passed","pleased to confirm"],"sample":"probation passed"},{"t":{"en":"Two strengths, with facts","tr":"Bilgileriyle iki güçlü yön","fa":"دو نقطه‌ی قوت با اطلاعات واقعی"},"find":["since you joined","saved"],"sample":"picking errors from 4% to 1.5%; two hours a day saved"},{"t":{"en":"One area to develop","tr":"Geliştirilecek bir alan","fa":"یک زمینه برای پیشرفت"},"find":["area to develop","delegation"],"sample":"delegation: she checks every route herself"},{"t":{"en":"What happens next","tr":"Sonra ne olacağı","fa":"اتفاق بعدی"},"find":["as a result","your contract continues"],"sample":"team leader course in April; same terms"}]},"speaking":{"id":"hr-cp-7-sp","course":"hr","unit":"hr-cp-7","rounds":[180,120],"topic":{"en":"A Return-to-Work Talk (recorded)","tr":"Bir İşe Dönüş Görüşmesi (kayıtlı)","fa":"گفتگوی بازگشت به کار (ضبط‌شده)"},"warmup":{"en":"Rania, the new warehouse planner, is back after three days off with migraines. It is her second absence in her first two months. She works long hours at a bright screen.","tr":"Yeni depo planlamacısı Rania, migren yüzünden üç gün izin aldıktan sonra döndü. İlk iki ayındaki ikinci devamsızlığı. Parlak bir ekran başında uzun saatler çalışıyor.","fa":"رانیا، برنامه‌ریز تازه‌ی انبار، بعد از سه روز غیبت به خاطر میگرن برگشته. این دومین غیبتش در دو ماه اول است. او ساعت‌های طولانی پشت یک صفحه‌ی نمایش پرنور کار می‌کند."},"questions":[{"en":"Welcome Rania back and say what the talk is for.","tr":"Rania’yı karşıla ve görüşmenin ne için olduğunu söyle.","fa":"به رانیا خوشامد بگو و بگو این گفتگو برای چیست."},{"en":"Mention the pattern calmly (present perfect) and ask about causes at work.","tr":"Örüntüden sakince bahset (present perfect) ve iş yerindeki nedenleri sor.","fa":"الگو را آرام بگو (حال کامل) و درباره‌ی علت‌های محیط کار بپرس."},{"en":"Agree one change and a check-in date.","tr":"Bir değişiklikte ve bir takip tarihinde anlaş.","fa":"روی یک تغییر و تاریخ پیگیری توافق کن."}],"followups":[{"en":"Say it out loud in 3 minutes, then in 2.","tr":"Yüksek sesle önce 3, sonra 2 dakikada söyle.","fa":"آن را با صدای بلند یک بار در سه دقیقه و بعد در دو دقیقه بگو."}],"expressions":[{"phrase":"Welcome back. How are you feeling?","meaning":{"en":"A kind opening.","tr":"Nazik bir açılış.","fa":"شروعی مهربان."}},{"phrase":"You've been off twice since you joined.","meaning":{"en":"States the pattern.","tr":"Örüntüyü söyler.","fa":"الگو را می‌گوید."}},{"phrase":"It might help to...","meaning":{"en":"Suggests a change gently.","tr":"Nazikçe bir değişiklik önerir.","fa":"با ملایمت تغییری را پیشنهاد می‌کند."}}]},"perspective":{"id":"c-hr-cp-7-p","course":"hr","unit":"hr-cp-7","type":"perspective","title":{"en":"Leyla, two years on","tr":"İki yıl sonra Leyla","fa":"لیلا، دو سال بعد"},"minSentences":3,"prompt":{"en":"You are Leyla. Two years ago you had sixty seconds to introduce yourself. Write 3 sentences in first person: which of the four HR essentials (checks, records, absence, letters) did you find hardest, and why?","tr":"Sen Leyla’sın. İki yıl önce kendini tanıtmak için altmış saniyen vardı. Birinci tekil şahısla 3 cümle yaz: İK’nın dört temelinden (kontroller, kayıtlar, devamsızlık, mektuplar) hangisini en zor buldun ve neden?","fa":"تو لیلا هستی. دو سال پیش شصت ثانیه وقت داشتی خودت را معرفی کنی. از زبان خودت سه جمله بنویس: از چهار اصل پایه‌ی منابع انسانی (بررسی‌ها، سوابق، غیبت، نامه‌ها) کدام برایت سخت‌تر بود و چرا؟"}},"exit":{"id":"c-hr-cp-7-x","course":"hr","unit":"hr-cp-7","type":"exit","note":"8 spaced items: all four Chapter 7 lessons plus four earlier chapters.","items":[{"from":"hr-7-1","kind":"blank","prompt":"All recruitment costs ___ by the company.","options":["are paid","pay","are pay"],"correct":0,"point":2,"why":{"en":"are paid: the costs receive the action, so are + past participle. 'Pay' says the costs pay something, and 'are pay' drops the participle.","tr":"are paid: maliyetler eylemi alır, bu yüzden are + üçüncü hâl. 'Pay' maliyetlerin bir şey ödediğini söyler; 'are pay' üçüncü hâli düşürür.","fa":"are paid درست است، چون هزینه‌ها پرداخت می‌شوند و are و اسم مفعول لازم است. pay یعنی خود هزینه‌ها چیزی می‌پردازند و are pay اسم مفعول ندارد."}},{"from":"hr-7-2","kind":"blank","prompt":"The candidate asked ___ the notes had been shared.","options":["whether","that","did"],"correct":0,"point":2,"why":{"en":"whether: a reported yes/no question uses whether (or if). 'That' reports a statement, and 'did' can't open a reported question.","tr":"whether: aktarılan evet/hayır sorusu whether (ya da if) kullanır. 'That' bir bildirimi aktarır; 'did' aktarılan soruyu başlatamaz.","fa":"whether درست است، چون برای نقل سؤال بله‌یا‌نه whether یا if می‌آید. that جمله‌ی خبری را نقل می‌کند و did سؤال نقل‌شده را شروع نمی‌کند."}},{"from":"hr-7-3","kind":"blank","prompt":"He ___ late four times since the new rota started.","options":["has been","was","is being"],"correct":0,"point":2,"why":{"en":"has been: 'since the new rota started' runs until now, so the present perfect. 'Was' is for finished time, and 'is being' doesn't go with since.","tr":"has been: 'since the new rota started' bugüne kadar sürer, bu yüzden present perfect. 'Was' bitmiş zaman içindir; 'is being' since ile kullanılmaz.","fa":"has been درست است، چون since the new rota started تا الان ادامه دارد و حال کامل می‌خواهد. was برای زمان تمام‌شده است و is being با since نمی‌آید."}},{"from":"hr-7-4","kind":"mcq","prompt":"Which sentence opens a formal outcome letter?","options":["Following our meeting on 3 June, we have reviewed the records.","Hi! Good news about your complaint!","So, about that thing you said."],"correct":0,"point":2,"why":{"en":"'Following our meeting on 3 June, we have reviewed the records' is formal and gives the date. 'Hi! Good news!' and 'So, about that thing' are too casual for an outcome letter.","tr":"'Following our meeting on 3 June, we have reviewed the records' resmîdir ve tarihi verir. 'Hi! Good news!' ve 'So, about that thing' bir sonuç yazısı için fazla gayriresmîdir.","fa":"«Following our meeting on 3 June, we have reviewed the records» رسمی است و تاریخ را می‌گوید. «Hi! Good news!» و «So, about that thing» برای نامه‌ی نتیجه زیادی خودمانی‌اند."}},{"from":"hr-6-1","kind":"blank","prompt":"Your basic salary rises ___ 4% next year.","options":["by","to","at"],"correct":0,"point":2,"why":{"en":"by: 'rises by 4%' gives the size of the rise. 'To' would need the new amount, and 'at' doesn't measure change.","tr":"by: 'rises by 4%' artışın miktarını verir. 'To' yeni tutarı ister; 'at' değişimi ölçmez.","fa":"by درست است، چون rises by 4% مقدار افزایش را می‌گوید. to مبلغ جدید را می‌خواهد و at تغییر را نمی‌سنجد."}},{"from":"hr-5-2","kind":"blank","prompt":"On Friday the report ___ sent to the wrong client.","options":["was","is","has"],"correct":0,"point":2,"why":{"en":"was: a finished event on Friday, and the report received the action: was + past participle. 'Is' is the present, and 'has sent' doesn't fit on Friday.","tr":"was: cuma günü bitmiş bir olay ve rapor eylemi aldı: was + üçüncü hâl. 'Is' şimdiki zamandır; 'has sent' on Friday ile uymaz.","fa":"was درست است، چون اتفاق جمعه تمام شده و گزارش فرستاده شده: was و اسم مفعول. is زمان حال است و has با on Friday جور نیست."}},{"from":"hr-3-3","kind":"blank","prompt":"She ___ us that she had trained new staff.","options":["told","said","spoke"],"correct":0,"point":2,"why":{"en":"told: 'tell' takes a person (told us). 'Said' takes no person, and 'spoke' doesn't report words this way.","tr":"told: 'tell' bir kişi alır (told us). 'Said' kişi almaz; 'spoke' sözleri bu şekilde aktarmaz.","fa":"told درست است، چون tell شخص می‌خواهد (told us). بعد از said شخص نمی‌آید و spoke حرف را این‌طور نقل نمی‌کند."}},{"from":"hr-1-2","kind":"blank","prompt":"Could you ___ the contract by Monday?","options":["sign","to sign","signing"],"correct":0,"point":2,"why":{"en":"sign: 'Could you' + plain verb. 'To sign' and 'signing' don't follow could.","tr":"sign: 'Could you' + yalın fiil. 'To sign' ve 'signing' could'dan sonra gelmez.","fa":"sign درست است، چون بعد از Could you فعل ساده می‌آید. to sign و signing بعد از could نمی‌آیند."}}]}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
